//! PQ-C: the sparse post-quantum root re-key (design §9.4; slice S13; Q48, Q49, Q68).
//!
//! A pair root is random and generated by the **recipient** of the direction it keys (§6.3). In
//! its classical form (`seal_root`, TLV 0x0001) the 32 bytes travel inside the E2E content of an
//! acknowledged session's normal Olm message, so a passive adversary that reads a device's state
//! once and breaks X25519 later follows every root that travels afterwards: nothing in the path
//! is post-quantum once the Olm ratchet is known. The PQ-C form (`seal_root_pq`, TLV 0x0005)
//! mixes an X-Wing shared secret into the root:
//!
//! ```text
//! (ct, ss) = XWing.Encaps(Q_c)                              Q_c: c's generation `peer_gen_id`
//! root     = HKDF-SHA256(ikm  = root_rand || ss,
//!                        salt = SHA-256("ghost/v1/dm/pq-root" || OI_me || OI_c
//!                                       || u32_be(peer_gen_id) || Q_c || ct),
//!                        info = "ghost/v1/dm/pq-root", L = 32)
//! TLV      = root_rand(32) || base_week(8) || root_gen(2) || peer_gen_id(4) || ct(1120)
//! ```
//!
//! **Roles, because the salt names two identities in an order.** `OI_me` is the Olm identity of
//! the device that **offers** the root (the recipient of direction `c → me`, which generates
//! `root_rand` and encapsulates); `OI_c` is the identity of the peer that will **seal** with it and
//! that decapsulates. Both sides therefore compute the salt as `SHA-256(label || OI_offerer ||
//! OI_target || ...)`: the offerer passes `(own, pinned peer)`, the opener `(pinned peer, own)`.
//! [`PqRootParties`] carries the two by role so a caller cannot swap them by position — a swapped
//! pair derives a different root and fails silently as "the peer sees nothing".
//!
//! **What the opener binds.** `Q_c` in the salt is the opener's **own** public key, recomputed from
//! the stored seed, never a value from the wire: an offer encapsulated to any other key derives a
//! different root even where ML-KEM's implicit rejection would hand back a secret. The generation
//! the TLV names must be the one the caller loaded (`NOT_OPEN` otherwise, §22.8.6 rule 3).
//!
//! **No key confirmation (declared, §22.18).** The TLV carries no tag over the derived root, by
//! the fixed 1 166-byte layout of §7.1. A decapsulation that yields a different `ss` — only
//! possible when the offerer used a key that is not the opener's key for `peer_gen_id` — returns a
//! root that is simply wrong. The design relies on every `Q_c` being authenticated (a signed
//! bundle, or an in-band `pq_key` inside the peer's own session) and on §22.8.6's discard rules to
//! keep the offerer from encapsulating to a key the peer no longer holds.

use crate::codec::SealRootPq;
use crate::derive::{self, KemSecret, PairRoot};
use crate::pq;
use crate::result::{DmCode, DmResult};
use zeroize::Zeroize;

/// The two Olm identities of the PQ-root salt, by role (see the module header).
#[derive(Clone, Copy, Debug)]
pub struct PqRootParties<'a> {
    /// The identity of the device that generated `root_rand` and encapsulated: the recipient of
    /// the direction the root keys.
    pub oi_offerer: &'a [u8; 32],
    /// The identity of the device the root is offered to, which decapsulates and seals with it.
    pub oi_target: &'a [u8; 32],
}

/// A freshly offered PQ root: the TLV value the offer carries and the root it derives.
pub struct PqRootOffer {
    /// The `seal_root_pq` TLV value (1 166 bytes when encoded).
    pub tlv: SealRootPq,
    /// The derived pair root, which the offerer keeps (wrapped) until it is acknowledged.
    pub root: PairRoot,
}

impl core::fmt::Debug for PqRootOffer {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_struct("PqRootOffer")
            .field("tlv", &self.tlv)
            .finish_non_exhaustive()
    }
}

/// Offers a PQ root with given randomness: the vector and equivalence-fixture path.
///
/// [`pq::encapsulate_with`] validates `peer_public` whole first (§22.8.2 rule 3), so a key with an
/// invalid ML-KEM half or a low-order X25519 half is [`DmCode::InvalidKey`] and nothing is
/// derived; every other encapsulation error is the same code (§22.8.2 rule 4), which the caller
/// answers by falling back to the classical `seal_root`.
#[allow(clippy::too_many_arguments)]
pub fn offer_with(
    root_rand: &PairRoot,
    kem_randomness: &[u8; pq::ENCAPS_RANDOMNESS_BYTES],
    parties: PqRootParties<'_>,
    peer_gen_id: u32,
    peer_public: &[u8],
    base_week: u64,
    root_gen: u16,
) -> DmResult<PqRootOffer> {
    let (ciphertext, shared) = pq::encapsulate_with(peer_public, kem_randomness)?;
    let root = derive::derive_pq_root(
        root_rand,
        &shared,
        parties.oi_offerer,
        parties.oi_target,
        peer_gen_id,
        peer_public,
        &ciphertext,
    );
    Ok(PqRootOffer {
        tlv: SealRootPq {
            root_rand: *root_rand.as_bytes(),
            base_week,
            root_gen,
            peer_gen_id,
            xwing_ct: ciphertext,
        },
        root,
    })
}

/// Offers a PQ root: `root_rand` and the encapsulation randomness from the OS CSPRNG (§9.2).
pub fn offer(
    parties: PqRootParties<'_>,
    peer_gen_id: u32,
    peer_public: &[u8],
    base_week: u64,
    root_gen: u16,
) -> DmResult<PqRootOffer> {
    let mut rand_bytes = [0u8; 32];
    pq::fill_random(&mut rand_bytes);
    let root_rand = PairRoot::from_bytes(rand_bytes);
    rand_bytes.zeroize();
    let mut randomness = [0u8; pq::ENCAPS_RANDOMNESS_BYTES];
    pq::fill_random(&mut randomness);
    let out = offer_with(
        &root_rand,
        &randomness,
        parties,
        peer_gen_id,
        peer_public,
        base_week,
        root_gen,
    );
    randomness.zeroize();
    out
}

/// Opens a received `seal_root_pq` with the generation it names (RECV R11, §9.4).
///
/// `gen_id` is the generation the caller loaded for the TLV's `peer_gen_id`; a mismatch, a
/// ciphertext that does not decapsulate (a low-order `ct_X`, §22.8.2 rule 5 d) or a seed that does
/// not expand is [`DmCode::NotOpen`] — the TLV is ignored and counted (§22.8.6 rule 3) and the
/// rest of the L0 applies. `Q_c` is recomputed from the seed, never read from the wire.
pub fn open(
    tlv: &SealRootPq,
    gen_id: u32,
    gen_seed: &KemSecret,
    parties: PqRootParties<'_>,
) -> DmResult<PairRoot> {
    if tlv.peer_gen_id != gen_id || tlv.xwing_ct.len() != pq::CIPHERTEXT_BYTES {
        return Err(DmCode::NotOpen);
    }
    let (shared, own_public) = pq::decapsulate_with_public(gen_seed, &tlv.xwing_ct)?;
    let root_rand = PairRoot::from_bytes(tlv.root_rand);
    Ok(derive::derive_pq_root(
        &root_rand,
        &shared,
        parties.oi_offerer,
        parties.oi_target,
        gen_id,
        &own_public,
        &tlv.xwing_ct,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use hkdf::Hkdf;
    use sha2::{Digest, Sha256};

    const OI_A: [u8; 32] = [0xa1; 32];
    const OI_B: [u8; 32] = [0xb2; 32];

    fn seed(byte: u8) -> KemSecret {
        KemSecret::from_bytes([byte; 32])
    }

    fn a_offers_to_b() -> PqRootParties<'static> {
        PqRootParties {
            oi_offerer: &OI_A,
            oi_target: &OI_B,
        }
    }

    /// The §9.4 formula written out with the primitives alone, independently of
    /// `derive::derive_pq_root`: a change to the label, the salt order or the ikm order fails here.
    fn spec_root(
        root_rand: &[u8; 32],
        ss: &[u8; 32],
        oi_me: &[u8; 32],
        oi_c: &[u8; 32],
        gen_id: u32,
        q_c: &[u8],
        ct: &[u8],
    ) -> [u8; 32] {
        let mut salt_input = Vec::new();
        salt_input.extend_from_slice(b"ghost/v1/dm/pq-root");
        salt_input.extend_from_slice(oi_me);
        salt_input.extend_from_slice(oi_c);
        salt_input.extend_from_slice(&gen_id.to_be_bytes());
        salt_input.extend_from_slice(q_c);
        salt_input.extend_from_slice(ct);
        let salt = Sha256::digest(&salt_input);
        let mut ikm = Vec::new();
        ikm.extend_from_slice(root_rand);
        ikm.extend_from_slice(ss);
        let hkdf = Hkdf::<Sha256>::new(Some(&salt), &ikm);
        let mut out = [0u8; 32];
        hkdf.expand(b"ghost/v1/dm/pq-root", &mut out)
            .expect("L = 32");
        out
    }

    #[test]
    fn an_offer_opens_to_the_same_root_on_the_other_side() {
        let b_seed = seed(0x11);
        let b_public = pq::public_key(&b_seed).expect("keygen");
        let offer = offer(a_offers_to_b(), 0x0102_0304, &b_public, 2_871, 7).expect("offer");
        assert_eq!(offer.tlv.root_gen, 7);
        assert_eq!(offer.tlv.base_week, 2_871);
        assert_eq!(offer.tlv.peer_gen_id, 0x0102_0304);
        assert_eq!(offer.tlv.xwing_ct.len(), pq::CIPHERTEXT_BYTES);
        // The TLV survives its own codec, which is how it travels.
        let wire = offer.tlv.encode().expect("encode");
        assert_eq!(wire.len(), crate::codec::SEAL_ROOT_PQ_BYTES);
        let received = SealRootPq::decode(&wire).expect("decode");
        let opened = open(&received, 0x0102_0304, &b_seed, a_offers_to_b()).expect("open");
        assert_eq!(opened.as_bytes(), offer.root.as_bytes());
        // And it is not the classical root: `root_rand` alone is not the key.
        assert_ne!(opened.as_bytes(), &received.root_rand);
    }

    /// The derivation, checked against the formula of §9.4 computed from the primitives.
    #[test]
    fn the_root_is_the_formula_of_section_9_4() {
        let b_seed = seed(0x12);
        let b_public = pq::public_key(&b_seed).expect("keygen");
        let root_rand = PairRoot::from_bytes([0x5c; 32]);
        let randomness = [0x5e; pq::ENCAPS_RANDOMNESS_BYTES];
        let offer = offer_with(
            &root_rand,
            &randomness,
            a_offers_to_b(),
            0x0506_0708,
            &b_public,
            2_872,
            4,
        )
        .expect("offer");
        let (ct, ss) = pq::encapsulate_with(&b_public, &randomness).expect("encaps");
        assert_eq!(
            offer.tlv.xwing_ct, ct,
            "the offer carries the encapsulation"
        );
        let expected = spec_root(
            &[0x5c; 32],
            ss.as_bytes(),
            &OI_A,
            &OI_B,
            0x0506_0708,
            &b_public,
            &ct,
        );
        assert_eq!(offer.root.as_bytes(), &expected);
        let opened = open(&offer.tlv, 0x0506_0708, &b_seed, a_offers_to_b()).expect("open");
        assert_eq!(opened.as_bytes(), &expected);
    }

    /// Every input of the salt and the ikm moves the root; the roles are not interchangeable.
    #[test]
    fn every_bound_input_moves_the_root() {
        let b_seed = seed(0x13);
        let b_public = pq::public_key(&b_seed).expect("keygen");
        let offer = offer(a_offers_to_b(), 9, &b_public, 2_873, 1).expect("offer");
        let root = *offer.root.as_bytes();

        // Swapped roles: the opener passing (own, peer) instead of (peer, own).
        let swapped = PqRootParties {
            oi_offerer: &OI_B,
            oi_target: &OI_A,
        };
        assert_ne!(
            open(&offer.tlv, 9, &b_seed, swapped)
                .expect("opens")
                .as_bytes(),
            &root
        );
        // Another identity on either side.
        let other = [0xc3; 32];
        for parties in [
            PqRootParties {
                oi_offerer: &other,
                oi_target: &OI_B,
            },
            PqRootParties {
                oi_offerer: &OI_A,
                oi_target: &other,
            },
        ] {
            assert_ne!(
                open(&offer.tlv, 9, &b_seed, parties)
                    .expect("opens")
                    .as_bytes(),
                &root
            );
        }
        // Another `root_rand`.
        let mut tampered = offer.tlv.clone();
        tampered.root_rand[0] ^= 1;
        assert_ne!(
            open(&tampered, 9, &b_seed, a_offers_to_b())
                .expect("opens")
                .as_bytes(),
            &root
        );
        // A flipped ciphertext byte: ML-KEM's implicit rejection gives another secret, and the
        // ciphertext is in the salt besides.
        let mut flipped = offer.tlv.clone();
        flipped.xwing_ct[0] ^= 1;
        assert_ne!(
            open(&flipped, 9, &b_seed, a_offers_to_b())
                .expect("opens")
                .as_bytes(),
            &root
        );
    }

    /// §22.8.6 rule 3: a generation other than the one named, or a seed that is not the target's,
    /// never yields the offered root.
    #[test]
    fn the_wrong_generation_does_not_open_and_another_seed_derives_another_root() {
        let b_seed = seed(0x14);
        let b_public = pq::public_key(&b_seed).expect("keygen");
        let offer = offer(a_offers_to_b(), 41, &b_public, 2_874, 2).expect("offer");
        assert_eq!(
            open(&offer.tlv, 42, &b_seed, a_offers_to_b()).err(),
            Some(DmCode::NotOpen),
            "a generation id other than the one the TLV names"
        );
        // The seed of another generation under the right id: the public key in the salt is the
        // opener's own, so the root differs even where decapsulation "succeeds".
        let other = open(&offer.tlv, 41, &seed(0x15), a_offers_to_b()).expect("implicit");
        assert_ne!(other.as_bytes(), offer.root.as_bytes());
    }

    /// §22.8.2 rules 3, 4 and 5: an invalid key is `INVALID_KEY` at the offer and a low-order
    /// `ct_X` is `NOT_OPEN` at the opening — typed, never a panic.
    #[test]
    fn invalid_keys_and_low_order_ciphertexts_are_typed_refusals() {
        let b_seed = seed(0x16);
        let b_public = pq::public_key(&b_seed).expect("keygen");
        for point in pq::low_order_points() {
            let mut bad = b_public.clone();
            bad[pq::ML_KEM_PUBLIC_KEY_BYTES..].copy_from_slice(&point);
            assert_eq!(
                offer(a_offers_to_b(), 1, &bad, 1, 1).err(),
                Some(DmCode::InvalidKey)
            );
        }
        let mut bad_ml_kem = b_public.clone();
        bad_ml_kem[0] = 0xff;
        bad_ml_kem[1] |= 0x0f;
        assert_eq!(
            offer(a_offers_to_b(), 1, &bad_ml_kem, 1, 1).err(),
            Some(DmCode::InvalidKey)
        );
        assert_eq!(
            offer(a_offers_to_b(), 1, &b_public[..1215], 1, 1).err(),
            Some(DmCode::InvalidKey)
        );

        let offer = offer(a_offers_to_b(), 3, &b_public, 1, 1).expect("offer");
        for point in pq::low_order_points() {
            let mut tlv = offer.tlv.clone();
            tlv.xwing_ct[pq::ML_KEM_CIPHERTEXT_BYTES..].copy_from_slice(&point);
            assert_eq!(
                open(&tlv, 3, &b_seed, a_offers_to_b()).err(),
                Some(DmCode::NotOpen)
            );
        }
        let mut short = offer.tlv.clone();
        short.xwing_ct.pop();
        assert_eq!(
            open(&short, 3, &b_seed, a_offers_to_b()).err(),
            Some(DmCode::NotOpen)
        );
    }

    /// Two offers to the same key never share a ciphertext or a root: `root_rand` and the
    /// encapsulation randomness are both fresh (§9.2, JD10's spirit for the PQ-C TLV).
    #[test]
    fn offers_are_fresh() {
        let b_public = pq::public_key(&seed(0x17)).expect("keygen");
        let first = offer(a_offers_to_b(), 5, &b_public, 1, 1).expect("offer");
        let second = offer(a_offers_to_b(), 5, &b_public, 1, 1).expect("offer");
        assert_ne!(first.tlv.xwing_ct, second.tlv.xwing_ct);
        assert_ne!(first.tlv.root_rand, second.tlv.root_rand);
        assert_ne!(first.root.as_bytes(), second.root.as_bytes());
    }

    #[test]
    fn an_offer_does_not_render_its_secrets() {
        let b_public = pq::public_key(&seed(0x18)).expect("keygen");
        let offer = offer(a_offers_to_b(), 5, &b_public, 1, 1).expect("offer");
        let rendered = format!("{offer:?}");
        assert!(!rendered.contains("root_rand: ["), "{rendered}");
        assert!(!rendered.contains("root:"), "{rendered}");
    }
}
